export const M3_SHAPE_NAMES: M3ShapeType[] = Object.keys(M3_SHAPES) as M3ShapeType[];

/**
 * Helper to retrieve precomputed smooth cubic bezier SVG path for any M3 shape.
 */
export function getM3ShapePath(shape: M3ShapeType): string {
  return M3_SHAPES[shape]?.pathD ?? M3_SHAPES.circle.pathD;
}

/**
 * Helper to retrieve SVG polygon points string ("x,y x,y ...") for any M3 shape.
 */
export function getM3ShapePolygon(shape: M3ShapeType): string {
  return M3_SHAPES[shape]?.points ?? M3_SHAPES.circle.points;
}

/**
 * Helper to retrieve CSS clip-path polygon("...") string for any M3 shape.
 */
export function getM3ShapeClipPath(shape: M3ShapeType): string {
  return M3_SHAPES[shape]?.clipPath ?? M3_SHAPES.circle.clipPath;
}

/* ==========================================================================
   M3SHAPE COMPONENT
   ========================================================================== */

export interface M3ShapeProps extends React.SVGProps<SVGSVGElement> {
  /** The M3 Expressive shape to render */
  shape: M3ShapeType;
  /** Size in pixels or CSS units (applied to width and height) */
  size?: number | string;
  /** Optional fill color (defaults to currentColor) */
  fill?: string;
  /** Optional stroke color */
  stroke?: string;
  /** Optional stroke width */
  strokeWidth?: number | string;
  /** Custom class name */
  className?: string;
  /** If children are provided or asMask is true, clips children to this shape */
  asMask?: boolean;
  /** Optional children to wrap inside the shape mask */
  children?: React.ReactNode;
}

/**
 * M3Shape: Renders pure Material 3 Expressive shapes as crisp SVGs or masks.
 *
 * @example
 * <M3Shape shape="cookie-4" size={48} className="text-primary" />
 * <M3Shape shape="clover" asMask><img src="..." alt="avatar" /></M3Shape>
 */
export const M3Shape: React.FC<M3ShapeProps> = ({
  shape,
  size = 48,
  fill = "currentColor",
  stroke = "none",
  strokeWidth = 0,
  className = "",
  asMask = false,
  children,
  style,
  ...svgProps
}) => {
  const pathD = getM3ShapePath(shape);
  const clipPathStyle = getM3ShapeClipPath(shape);

  if (children || asMask) {
    return (
      <div
        className={"relative inline-flex items-center justify-center overflow-hidden " + className}
        style={{
          width: typeof size === "number" ? size + "px" : size,
          height: typeof size === "number" ? size + "px" : size,
          clipPath: clipPathStyle,
          WebkitClipPath: clipPathStyle,
          ...style,
        }}
      >
        {children}
      </div>
    );
  }

  return (
    <svg
      viewBox="0 0 100 100"
      width={size}
      height={size}
      className={"inline-block shrink-0 " + className}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      style={style}
      {...svgProps}
    >
      <path
        d={pathD}
        fill={fill}
        stroke={stroke}
        strokeWidth={strokeWidth}
        vectorEffect="non-scaling-stroke"
      />
    </svg>
  );
};

/* ==========================================================================
   EXPRESSIVE SHAPE MORPH COMPONENT
   ========================================================================== */

export interface ExpressiveShapeMorphProps {
  /** The default/idle shape */
  shape?: M3ShapeType;
  /** Shape to morph into when hovered */
  hoverShape?: M3ShapeType;
  /** Shape to morph into when pressed/active */
  activeShape?: M3ShapeType;
  /** External controlled shape */
  targetShape?: M3ShapeType;
  /** Dimension in pixels or CSS dimension (default: 64) */
  size?: number | string;
  /** SVG fill color (defaults to currentColor) */
  fill?: string;
  /** SVG stroke color */
  stroke?: string;
  /** SVG stroke width */
  strokeWidth?: number | string;
  /** Additional CSS classes */
  className?: string;
  /** Spring physics tuning */
  springConfig?: {
    stiffness?: number;
    damping?: number;
    mass?: number;
  };
  /** Optional click handler */
  onClick?: () => void;
  /** Optional children displayed inside the morphing shape */
  children?: React.ReactNode;
}

/**
 * ExpressiveShapeMorph: Interactive shape-morphing component driven by Framer Motion spring physics.
 * Transitions smoothly between any two M3 Expressive silhouettes on hover, active press, or state changes.
 *
 * @example
 * <ExpressiveShapeMorph shape="cookie-4" hoverShape="circle" size={64} />
 * <ExpressiveShapeMorph shape="sunny" activeShape="squircle" size={80} />
 */
export const ExpressiveShapeMorph: React.FC<ExpressiveShapeMorphProps> = ({
  shape = "cookie-4",
  hoverShape,
  activeShape,
  targetShape,
  size = 64,
  fill = "currentColor",
  stroke = "none",
  strokeWidth = 0,
  className = "",
  springConfig,
  onClick,
  children,
}) => {
  const [isHovered, setIsHovered] = useState(false);
  const [isPressed, setIsPressed] = useState(false);
  const clipId = useId();

  // Resolve current active shape
  const resolvedShape: M3ShapeType =
    targetShape ??
    (isPressed && activeShape
      ? activeShape
      : isHovered && hoverShape
      ? hoverShape
      : shape);

  const currentPath = getM3ShapePath(resolvedShape);

  const springTransition: Transition = {
    type: "spring",
    stiffness: springConfig?.stiffness ?? 340,
    damping: springConfig?.damping ?? 24,
    mass: springConfig?.mass ?? 0.8,
  };

  const dim = typeof size === "number" ? size + "px" : size;

  return (
    <div
      className={"relative inline-flex items-center justify-center select-none " + className}
      style={{ width: dim, height: dim }}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => {
        setIsHovered(false);
        setIsPressed(false);
      }}
      onMouseDown={() => setIsPressed(true)}
      onMouseUp={() => setIsPressed(false)}
      onTouchStart={() => setIsPressed(true)}
      onTouchEnd={() => setIsPressed(false)}
      onClick={onClick}
      role={onClick ? "button" : undefined}
      tabIndex={onClick ? 0 : undefined}
    >
      <svg
        viewBox="0 0 100 100"
        width="100%"
        height="100%"
        className="absolute inset-0 overflow-visible pointer-events-none"
        xmlns="http://www.w3.org/2000/svg"
      >
        <defs>
          <clipPath id={clipId}>
            <motion.path
              d={currentPath}
              animate={{ d: currentPath }}
              transition={springTransition}
            />
          </clipPath>
        </defs>
        <motion.path
          d={currentPath}
          animate={{ d: currentPath }}
          transition={springTransition}
          fill={fill}
          stroke={stroke}
          strokeWidth={strokeWidth}
          vectorEffect="non-scaling-stroke"
        />
      </svg>

      {children && (
        <div
          className="relative z-10 w-full h-full flex items-center justify-center overflow-hidden"
          style={{
            clipPath: "url(#" + clipId + ")",
            WebkitClipPath: "url(#" + clipId + ")",
          }}
        >
          {children}
        </div>
      )}
    </div>
  );
};
